import { useEffect, useState, useCallback, useRef, useMemo } from 'react';
import { Database, RefreshCw, AlertTriangle, Search, Loader2, FolderKanban, Menu, ShieldAlert, AlertCircle } from 'lucide-react';
import Sidebar, { displayTitle, type SidebarView } from '@/components/Sidebar';
import LanguageSelector from '@/components/LanguageSelector';
import CollectionViewer from '@/components/TableViewer';
import AnalyticsDashboard from '@/components/AnalyticsDashboard';
import TableBuilder from '@/components/TableBuilder';
import ReportCenter from '@/components/ReportCenter';
import ConfigBanner from '@/components/ConfigBanner';
import LoginPage from '@/components/LoginPage';
import MainAdminPage from '@/components/MainAdminPage';
import { ErrorBoundary } from '@/components/ErrorBoundary';
import { useAuth } from '@/hooks/useAuth';
import { useBranding } from '@/hooks/useBranding';
import { useProject } from '@/hooks/useProject';
import type { Project } from '@/contexts/ProjectContext';
import type { ProjectRole } from '@/contexts/ProjectContext';

import {
  fetchCollectionsForProject,
  fetchCollectionsByPrefix,
  fetchRecords,
  fetchProjectTableVisibility,
  getConfigStatus,
  DatabaseError,
} from '@/services/database';
import type { TableCollection } from '@/types/database';
import { TLM_PRIMARY } from '@/config/theme';
import { useLanguage } from '@/hooks/useLanguage';
import { useToast } from '@/components/Toast';

type Route = 'main' | 'project';

function getProjectIdFromUrl(): string | null {
  const m = window.location.pathname.match(/^\/projeto\/([^/?#]+)/);
  return m ? decodeURIComponent(m[1]) : null;
}

function setProjectUrl(projectId: string) {
  const url = `/projeto/${encodeURIComponent(projectId)}`;
  if (window.location.pathname !== url) {
    window.history.pushState({ projectId }, '', url);
  }
}

function clearProjectUrl() {
  if (window.location.pathname.startsWith('/projeto/')) {
    window.history.pushState({}, '', '/');
  }
}

export default function App() {
  const { user, role, token, loading: authLoading, assignedProjects, login, logout, validateProjectRole, serverActiveProjectId, serverActiveProject, refreshActiveProject } = useAuth();
  const { loading: brandingLoading } = useBranding();
  const {
    activeProject, projects, setProjects, setActiveProject,
    projectRole, setProjectRole, accessDenied, setAccessDenied,
    resetProjectState, tablePrefix,
  } = useProject();
  const [collections, setCollections] = useState<TableCollection[]>([]);
  const [projectHiddenTables, setProjectHiddenTables] = useState<Set<string>>(new Set());
  const [activeCollection, setActiveCollection] = useState<TableCollection | null>(null);
  const [search, setSearch] = useState('');
  const [loadingCollections, setLoadingCollections] = useState(true);
  const [collectionsError, setCollectionsError] = useState<string | null>(null);
  const [loadingProjects, setLoadingProjects] = useState(false);
  const [view, setView] = useState<SidebarView>('dashboard');
  const [route, setRoute] = useState<Route>('project');
  const [routeReady, setRouteReady] = useState(false);
  const [mobileSidebarOpen, setMobileSidebarOpen] = useState(false);
  const [validatingAccess, setValidatingAccess] = useState(false);
  const [validationError, setValidationError] = useState<string | null>(null);
  const { t } = useLanguage();
  const { notify } = useToast();
  const lastProjectId = useRef<string | null>(null);

  const { configured, missing } = getConfigStatus();

  useEffect(() => {
    if (authLoading || !user) return;
    const urlProjectId = getProjectIdFromUrl();
    if (urlProjectId) {
      setRoute('project');
      setRouteReady(true);
      return;
    }
    if (serverActiveProjectId) {
      setRoute('project');
      setRouteReady(true);
      return;
    }
    setRoute('main');
    resetProjectState();
    setRouteReady(true);
  }, [user, authLoading, serverActiveProjectId, resetProjectState]);

  useEffect(() => {
    if (!user) return;
    const handler = () => {
      if (document.visibilityState === 'visible') {
        refreshActiveProject();
      }
    };
    document.addEventListener('visibilitychange', handler);
    return () => document.removeEventListener('visibilitychange', handler);
  }, [user, refreshActiveProject]);

  const loadProjects = useCallback(async () => {
    setLoadingProjects(true);
    try {
      if (role === 'super_admin' || role === 'admin') {
        const data = await fetchRecords('projetos', { page: 1, pageSize: 100 });
        const projectList: Project[] = (data.data ?? []).map((r) => ({
          id: String(r.id),
          nome: r.nome as string,
          descricao: r.descricao as string | null,
          status: r.status as string | null,
          table_prefix: (r.table_prefix as string | null) ?? null,
        }));
        setProjects(projectList);
      } else {
        setProjects(assignedProjects);
      }
    } catch {
      setProjects([]);
    } finally {
      setLoadingProjects(false);
    }
  }, [setProjects, role, assignedProjects, token]);

  useEffect(() => {
    if (!user || !activeProject || route !== 'project') return;
    const currentId = String(activeProject.id);
    if (lastProjectId.current === currentId) return;
    lastProjectId.current = currentId;

    if (!currentId || currentId === 'undefined' || currentId === 'null') {
      setValidationError(t('security.invalidProjectDesc'));
      setValidatingAccess(false);
      setAccessDenied(true);
      setProjectRole('none');
      return;
    }

    let cancelled = false;
    setValidatingAccess(true);
    setAccessDenied(false);
    setValidationError(null);

    const timeoutId = setTimeout(() => {
      if (cancelled) return;
      setValidatingAccess(false);
      setValidationError(t('security.validationFailedDesc'));
      setAccessDenied(true);
      setProjectRole('none');
      notify('error', t('security.validationFailedDesc'));
    }, 10000);

    validateProjectRole(activeProject.id)
      .then((validatedRole: ProjectRole) => {
        if (cancelled) return;
        if (validatedRole === 'none') {
          setAccessDenied(true);
          setProjectRole('none');
          setCollections([]);
          setActiveCollection(null);
        } else {
          setAccessDenied(false);
          setProjectRole(validatedRole);
        }
      })
      .catch(() => {
        if (cancelled) return;
        setAccessDenied(true);
        setProjectRole('none');
        setValidationError(t('security.validationFailedDesc'));
        notify('error', t('security.validationFailedDesc'));
      })
      .finally(() => {
        clearTimeout(timeoutId);
        setValidatingAccess(false);
      });

    return () => { cancelled = true; clearTimeout(timeoutId); };
  }, [user, activeProject, route, validateProjectRole, setAccessDenied, setProjectRole, notify, t]);

  const loadCollections = useCallback(async (signal?: AbortSignal) => {
    if (!activeProject || !activeProject.id || String(activeProject.id) === 'undefined') {
      setCollections([]);
      setActiveCollection(null);
      setLoadingCollections(false);
      return;
    }
    setLoadingCollections(true);
    setCollectionsError(null);
    try {
      const prefixes = tablePrefix ? [tablePrefix] : [];
      const isSuperAdmin = role === 'super_admin';
      const data = await fetchCollectionsForProject(prefixes, {
        includeMaster: isSuperAdmin,
        signal,
      });
      setCollections(data);
      if (data.length > 0) {
        const sorted = [...data].sort((a, b) => displayTitle(a).localeCompare(displayTitle(b)));
        setActiveCollection((prev) => (prev && data.find((c) => c.name === prev.name) ? prev : sorted[0]));
      } else {
        setActiveCollection(null);
      }
    } catch (err) {
      if (err instanceof DOMException && err.name === 'AbortError') return;
      const msg = err instanceof DatabaseError ? err.message : 'Falha ao carregar as tabelas.';
      setCollectionsError(msg);
      setCollections([]);
    } finally {
      setLoadingCollections(false);
    }
  }, [activeProject, tablePrefix, role]);

  useEffect(() => {
    if (!configured || !user) {
      setLoadingCollections(false);
      return;
    }
    loadProjects();
  }, [configured, user, loadProjects]);

  useEffect(() => {
    if (!user || route !== 'project' || activeProject) return;
    const urlProjectId = getProjectIdFromUrl();
    const projectIdToRestore = urlProjectId ?? serverActiveProjectId;
    if (!projectIdToRestore) return;

    if (projects.length > 0) {
      const found = projects.find((p) => String(p.id) === String(projectIdToRestore));
      if (found) {
        setActiveProject(found);
        if (!urlProjectId) setProjectUrl(String(found.id));
        return;
      }
    }

    if (!urlProjectId && serverActiveProject && String(serverActiveProject.id) === String(projectIdToRestore)) {
      const proj: Project = {
        id: serverActiveProject.id,
        nome: serverActiveProject.nome ?? 'Projeto',
        table_prefix: serverActiveProject.table_prefix,
      };
      setActiveProject(proj);
      setProjectUrl(String(proj.id));
      return;
    }

    if (!urlProjectId && serverActiveProjectId) {
      notify('info', 'O projeto ativo foi removido ou desatribuido. Selecione outro projeto.');
    }
    setRoute('main');
    resetProjectState();
    clearProjectUrl();
  }, [user, route, projects, activeProject, serverActiveProjectId, serverActiveProject, setActiveProject, resetProjectState, notify]);

  useEffect(() => {
    const handler = () => {
      const urlProjectId = getProjectIdFromUrl();
      if (urlProjectId && projects.length > 0) {
        const found = projects.find((p) => String(p.id) === urlProjectId);
        if (found) {
          setActiveProject(found);
          setRoute('project');
          return;
        }
      }
      setRoute('main');
      resetProjectState();
      clearProjectUrl();
    };
    window.addEventListener('popstate', handler);
    return () => window.removeEventListener('popstate', handler);
  }, [projects, setActiveProject, resetProjectState]);

  useEffect(() => {
    if (!configured || !user || !activeProject || route !== 'project' || accessDenied || validatingAccess) {
      if (!activeProject || accessDenied) setLoadingCollections(false);
      return;
    }
    const controller = new AbortController();
    loadCollections(controller.signal);
    return () => controller.abort();
  }, [configured, user, activeProject, route, accessDenied, validatingAccess, loadCollections]);

  useEffect(() => {
    if (!activeProject || role === 'super_admin') {
      setProjectHiddenTables(new Set());
      return;
    }
    let cancelled = false;
    Promise.all([
      fetchProjectTableVisibility(activeProject.id, user?.id ?? null),
      fetchProjectTableVisibility(activeProject.id, undefined, role),
    ])
      .then(([userRows, roleRows]) => {
        if (cancelled) return;
        const hidden = new Set<string>();
        for (const row of userRows) {
          if (!row.visible) hidden.add(row.collection_name);
        }
        for (const row of roleRows) {
          if (!row.visible) hidden.add(row.collection_name);
        }
        setProjectHiddenTables(hidden);
      })
      .catch(() => {
        if (!cancelled) setProjectHiddenTables(new Set());
      });
    return () => { cancelled = true; };
  }, [activeProject, role, user]);

  const visibleCollections = useMemo(
    () => collections.filter((c) => !projectHiddenTables.has(c.name)),
    [collections, projectHiddenTables],
  );

  const handleSelectCollection = (collection: TableCollection) => {
    setActiveCollection(collection);
  };

  const handleRetry = () => {
    loadCollections();
  };

  const handleTableCreated = () => {
    loadCollections();
    setView('table');
  };

  const handleTableDeleted = (collectionName: string) => {
    if (activeCollection?.name === collectionName) {
      setActiveCollection(null);
    }
    loadCollections();
  };

  const handleEnterProject = (project: Project) => {
    setCollections([]);
    setActiveCollection(null);
    setSearch('');
    setView('dashboard');
    setAccessDenied(false);
    setProjectRole('none');
    setValidationError(null);
    lastProjectId.current = null;
    setActiveProject(project);
    setRoute('project');
    setProjectUrl(String(project.id));
  };

  const handleBackToAdmin = () => {
    setRoute('main');
    resetProjectState();
    setCollections([]);
    setActiveCollection(null);
    setSearch('');
    setView('dashboard');
    setValidationError(null);
    lastProjectId.current = null;
    clearProjectUrl();
  };

  const handleProjectSelect = (p: Project) => {
    setCollections([]);
    setActiveCollection(null);
    setSearch('');
    setView('dashboard');
    setAccessDenied(false);
    setProjectRole('none');
    setValidationError(null);
    lastProjectId.current = null;
    setActiveProject(p);
    setProjectUrl(String(p.id));
  };

  const showTableBuilder = (role === 'super_admin' || role === 'admin' || projectRole === 'admin_projeto');

  if (!configured) {
    return (
      <div className="flex h-screen bg-slate-50">
        <ConfigBanner missing={missing} />
      </div>
    );
  }

  if (authLoading || brandingLoading) {
    return (
      <div className="flex h-screen items-center justify-center bg-slate-50">
        <div className="flex flex-col items-center gap-4">
          <Loader2 className="h-8 w-8 animate-spin text-slate-400" />
          <p className="text-sm text-slate-400">A carregar...</p>
        </div>
      </div>
    );
  }

  if (!user) {
    return <LoginPage onLogin={login} />;
  }

  if (route === 'main') {
    return <MainAdminPage onEnterProject={handleEnterProject} />;
  }

  const sidebarUser = user
    ? { name: user.nickname || user.username || user.email, email: user.email, role }
    : null;

  if (accessDenied && activeProject) {
    const isValidationError = validationError !== null;
    return (
      <div className="flex h-screen items-center justify-center bg-slate-50 p-4">
        <div className="max-w-md rounded-2xl border border-rose-200 bg-white p-8 text-center shadow-lg">
          <div className="mx-auto mb-4 flex h-16 w-16 items-center justify-center rounded-full bg-rose-100">
            {isValidationError ? <AlertCircle className="h-8 w-8 text-rose-600" /> : <ShieldAlert className="h-8 w-8 text-rose-600" />}
          </div>
          <h2 className="text-xl font-bold text-rose-900">
            {isValidationError ? t('security.validationFailed') : t('security.accessDenied')}
          </h2>
          <p className="mt-2 text-sm text-rose-700">
            {isValidationError ? validationError : t('security.accessDeniedDesc')}
          </p>
          <button
            onClick={() => {
              setValidationError(null);
              if (role === 'super_admin') {
                handleBackToAdmin();
              } else {
                resetProjectState();
                setRoute('main');
              }
            }}
            className="mt-6 inline-flex items-center gap-2 rounded-lg bg-rose-600 px-4 py-2.5 text-sm font-semibold text-white transition hover:bg-rose-700"
          >
            <FolderKanban className="h-4 w-4" />
            {t('security.backToProjects')}
          </button>
        </div>
      </div>
    );
  }

  if (validatingAccess && activeProject) {
    return (
      <div className="flex h-screen items-center justify-center bg-slate-50">
        <div className="flex flex-col items-center gap-4">
          <Loader2 className="h-8 w-8 animate-spin text-slate-400" />
          <p className="text-sm text-slate-500">A validar acesso ao projeto...</p>
        </div>
      </div>
    );
  }

  if (route === 'project' && !activeProject && !loadingProjects && projects.length === 0 && !serverActiveProject && routeReady) {
    return (
      <div className="flex h-screen items-center justify-center bg-slate-50 p-4">
        <div className="max-w-md rounded-2xl border border-slate-200 bg-white p-8 text-center shadow-lg">
          <div className="mx-auto mb-4 flex h-16 w-16 items-center justify-center rounded-full bg-slate-100">
            <FolderKanban className="h-8 w-8 text-slate-400" />
          </div>
          <h2 className="text-xl font-bold text-slate-800">Nenhum projeto ativo atribuído</h2>
          <p className="mt-2 text-sm text-slate-500">
            Não existe um projeto ativo associado ao seu utilizador. Peça ao administrador para atribuir um projeto na Supabase.
          </p>
          <button
            onClick={handleBackToAdmin}
            className="mt-6 inline-flex items-center gap-2 rounded-lg px-4 py-2.5 text-sm font-semibold text-white transition hover:opacity-90"
            style={{ background: TLM_PRIMARY }}
          >
            <FolderKanban className="h-4 w-4" />
            Ver projetos disponíveis
          </button>
        </div>
      </div>
    );
  }

  return (
    <div className="flex h-screen overflow-hidden bg-slate-50 font-sans antialiased">
      <Sidebar
        collections={visibleCollections}
        activeCollectionName={activeCollection?.name ?? null}
        onSelect={handleSelectCollection}
        search={search}
        onSearchChange={setSearch}
        loading={loadingCollections}
        user={sidebarUser}
        onLogout={() => { logout(); resetProjectState(); setRoute('main'); }}
        projects={projects}
        activeProject={activeProject}
        onProjectSelect={handleProjectSelect}
        view={view}
        onViewChange={setView}
        isOlikanassa={!tablePrefix}
        showTableBuilder={showTableBuilder}
        isSuperAdmin={role === 'super_admin'}
        tablePrefix={tablePrefix}
        onBackToAdmin={handleBackToAdmin}
        mobileOpen={mobileSidebarOpen}
        onMobileClose={() => setMobileSidebarOpen(false)}
      />

      <main className="flex flex-1 flex-col overflow-hidden">
        <div className="flex items-center gap-3 border-b border-slate-200 bg-white px-4 py-3 lg:hidden">
          <button
            onClick={() => setMobileSidebarOpen(true)}
            aria-label={t('sidebar.openMenu')}
            className="flex h-10 w-10 items-center justify-center rounded-lg border border-slate-200 text-slate-600 transition hover:bg-slate-50"
          >
            <Menu className="h-5 w-5" />
          </button>
          <div className="flex items-center gap-2">
            <div className="flex h-8 w-8 items-center justify-center rounded-lg text-white" style={{ background: TLM_PRIMARY }}>
              <Database className="h-4 w-4" />
            </div>
            <span className="text-sm font-bold text-slate-900">{t('sidebar.appName')}</span>
          </div>
          <LanguageSelector compact />
        </div>
        <div className="flex flex-1 flex-col overflow-hidden">
        <ErrorBoundary onRetry={handleRetry}>
          {!activeProject && !loadingProjects && projects.length > 0 ? (
            <div className="flex h-full items-center justify-center p-8">
              <div className="max-w-md rounded-2xl border border-slate-200 bg-white p-8 text-center">
                <div className="mx-auto mb-4 flex h-12 w-12 items-center justify-center rounded-full bg-slate-100">
                  <FolderKanban className="h-6 w-6 text-slate-400" />
                </div>
                <h3 className="text-lg font-semibold text-slate-700">{t('admin.selectProjectPrompt')}</h3>
                <p className="mt-2 text-sm text-slate-500">
                  {t('admin.selectProjectDesc')}
                </p>
              </div>
            </div>
          ) : loadingProjects && !activeProject ? (
            <div className="flex h-full items-center justify-center p-8">
              <div className="flex flex-col items-center gap-4">
                <div className="h-10 w-10 animate-spin rounded-full border-2 border-slate-200 border-t-slate-900" />
                <p className="text-sm text-slate-500">{t('table.loading')}</p>
              </div>
            </div>
          ) : collectionsError ? (
            <div className="flex h-full items-center justify-center p-8">
              <div className="max-w-md rounded-2xl border border-rose-200 bg-rose-50/60 p-6 text-center">
                <div className="mx-auto mb-4 flex h-12 w-12 items-center justify-center rounded-full bg-rose-100">
                  <AlertTriangle className="h-6 w-6 text-rose-600" />
                </div>
                <h3 className="text-lg font-semibold text-rose-900">Erro ao carregar tabelas</h3>
                <p className="mt-2 text-sm text-rose-700">{collectionsError}</p>
                <button
                  onClick={handleRetry}
                  className="mt-4 inline-flex items-center gap-2 rounded-lg bg-rose-600 px-4 py-2 text-sm font-medium text-white transition hover:bg-rose-700"
                >
                  <RefreshCw className="h-4 w-4" />
                  Tentar novamente
                </button>
              </div>
            </div>
          ) : view === 'builder' && showTableBuilder ? (
            <TableBuilder
              collections={visibleCollections}
              onTableCreated={handleTableCreated}
              onTableDeleted={handleTableDeleted}
            />
          ) : view === 'reports' ? (
            <ReportCenter collections={visibleCollections} />
          ) : view === 'dashboard' ? (
            <AnalyticsDashboard collections={visibleCollections} />
          ) : loadingCollections && !activeCollection ? (
            <div className="flex h-full items-center justify-center p-8">
              <div className="flex flex-col items-center gap-4">
                <div className="h-10 w-10 animate-spin rounded-full border-2 border-slate-200 border-t-slate-900" />
                <p className="text-sm text-slate-500">A carregar tabelas...</p>
              </div>
            </div>
          ) : activeCollection ? (
            <CollectionViewer key={activeCollection.name} collection={activeCollection} />
          ) : !loadingCollections && collections.length === 0 ? (
            <div className="flex h-full items-center justify-center p-8">
              <div className="max-w-md rounded-2xl border border-slate-200 bg-white p-8 text-center">
                <div className="mx-auto mb-4 flex h-12 w-12 items-center justify-center rounded-full bg-slate-100">
                  <Database className="h-6 w-6 text-slate-400" />
                </div>
                <h3 className="text-lg font-semibold text-slate-700">{t('sidebar.noTableFound')}</h3>
                <p className="mt-2 text-sm text-slate-500">
                  {showTableBuilder
                    ? t('sidebar.tableConfig')
                    : t('sidebar.noTableFound')}
                </p>
              </div>
            </div>
          ) : (
            <div className="flex h-full items-center justify-center p-8">
              <div className="text-center">
                <div className="mx-auto mb-4 flex h-12 w-12 items-center justify-center rounded-full bg-slate-100">
                  <Search className="h-6 w-6 text-slate-400" />
                </div>
                <p className="text-sm text-slate-500">{t('sidebar.searchTables')}</p>
              </div>
            </div>
          )}
        </ErrorBoundary>
        </div>
      </main>
    </div>
  );
}

import { useState, useCallback, useEffect } from 'react';
import { ShieldCheck, Loader2, AlertCircle, RefreshCw, Eye, Crown, Pencil, UserCircle } from 'lucide-react';
import { fetchUsersWithProjects, DatabaseError, type UserWithProject } from '@/services/database';
import { TLM_PRIMARY, TLM_SECONDARY } from '@/config/theme';

function roleBadgeClass(roles: string | null): string {
  if (!roles) return 'bg-slate-100 text-slate-500 ring-1 ring-slate-200';
  const r = roles.trim().toLowerCase();
  if (r.includes('admin') || r === 'root' || r === 'super_admin')
    return 'bg-amber-50 text-amber-700 ring-1 ring-amber-200';
  if (r.includes('editor') || r.includes('merl') || r.includes('officer') || r.includes('focal'))
    return 'bg-blue-50 text-blue-700 ring-1 ring-blue-200';
  if (r.includes('leitor') || r.includes('viewer') || r.includes('member'))
    return 'bg-slate-100 text-slate-600 ring-1 ring-slate-200';
  return 'bg-slate-100 text-slate-500 ring-1 ring-slate-200';
}

function roleIcon(roles: string | null) {
  if (!roles) return <Eye className="h-3 w-3" />;
  const r = roles.trim().toLowerCase();
  if (r.includes('admin') || r === 'root' || r === 'super_admin') return <Crown className="h-3 w-3" />;
  if (r.includes('editor') || r.includes('merl') || r.includes('officer') || r.includes('focal')) return <Pencil className="h-3 w-3" />;
  return <Eye className="h-3 w-3" />;
}

function roleLabel(roles: string | null): string {
  if (!roles) return 'Sem role';
  const r = roles.trim().toLowerCase();
  if (r.includes('admin') || r === 'root' || r === 'super_admin') return 'Administrador';
  if (r.includes('editor') || r.includes('merl') || r.includes('officer') || r.includes('focal')) return 'Editor';
  if (r.includes('leitor') || r.includes('viewer') || r.includes('member')) return 'Leitor';
  return roles;
}

export default function AccessMatrix() {
  const [users, setUsers] = useState<UserWithProject[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  const loadUsers = useCallback(async () => {
    setLoading(true);
    setError(null);
    try {
      const data = await fetchUsersWithProjects();
      setUsers(data);
    } catch (err) {
      if (err instanceof DatabaseError) {
        if (err.status === 401 || err.status === 403) {
          setError('Erro ao conectar ao servidor externo Supabase: acesso não autorizado (401/403).');
        } else {
          setError(`Erro ao conectar ao servidor externo Supabase (${err.status}): ${err.message}`);
        }
      } else {
        setError('Erro ao conectar ao servidor externo Supabase. Verifique a ligação de rede.');
      }
      setUsers([]);
    } finally {
      setLoading(false);
    }
  }, []);

  useEffect(() => {
    loadUsers();
  }, [loadUsers]);

  const usersWithProject = users.filter((u) => u.active_project);
  const usersWithoutProject = users.filter((u) => !u.active_project);

  return (
    <div className="rounded-2xl border border-slate-200 bg-white shadow-sm">
      {/* Header */}
      <div className="flex flex-col gap-3 border-b border-slate-200 px-5 py-4 md:flex-row md:items-center md:justify-between">
        <div className="flex items-center gap-3">
          <div className="flex h-10 w-10 items-center justify-center rounded-xl text-white" style={{ background: `linear-gradient(135deg, ${TLM_PRIMARY}, ${TLM_SECONDARY})` }}>
            <ShieldCheck className="h-5 w-5" />
          </div>
          <div>
            <h3 className="text-base font-bold text-slate-800">Matriz de Controlo de Acessos</h3>
            <p className="text-xs text-slate-500">Espelho de consulta (só leitura) dos utilizadores e projetos ativos no Supabase</p>
          </div>
        </div>
        <button
          onClick={loadUsers}
          disabled={loading}
          className="inline-flex items-center justify-center gap-2 rounded-lg border border-slate-200 bg-white px-3 py-2 text-sm font-medium text-slate-600 transition hover:bg-slate-50 disabled:opacity-50"
        >
          <RefreshCw className={`h-4 w-4 ${loading ? 'animate-spin' : ''}`} />
          <span className="hidden sm:inline">Atualizar</span>
        </button>
      </div>

      {/* Read-only notice */}
      <div className="flex items-center gap-2 border-b border-slate-100 bg-sky-50 px-5 py-2.5">
        <Eye className="h-3.5 w-3.5 text-sky-600" />
        <p className="text-xs text-sky-700">
          Modo de consulta. Os vínculos e atribuições são geridos centralmente no painel nativo do Supabase.
        </p>
      </div>

      {/* Error */}
      {error && (
        <div className="mx-5 mt-4 flex items-start gap-3 rounded-xl border border-rose-200 bg-rose-50 p-4">
          <AlertCircle className="mt-0.5 h-5 w-5 shrink-0 text-rose-600" />
          <div className="flex-1">
            <p className="text-sm font-medium text-rose-900">Erro ao conectar ao servidor externo Supabase</p>
            <p className="mt-1 text-sm text-rose-700">{error}</p>
          </div>
        </div>
      )}

      {/* Loading */}
      {loading ? (
        <div className="flex flex-col items-center justify-center py-16">
          <Loader2 className="h-8 w-8 animate-spin text-slate-400" />
          <p className="mt-3 text-sm text-slate-500">A carregar utilizadores do Supabase...</p>
        </div>
      ) : error ? null : users.length === 0 ? (
        <div className="flex flex-col items-center justify-center py-12">
          <div className="mb-3 flex h-12 w-12 items-center justify-center rounded-full bg-slate-100">
            <UserCircle className="h-6 w-6 text-slate-400" />
          </div>
          <p className="text-sm font-medium text-slate-600">Nenhum utilizador encontrado</p>
          <p className="mt-1 text-xs text-slate-400">O servidor Supabase não retornou dados de utilizadores.</p>
        </div>
      ) : (
        <div className="px-5 py-4">
          {/* Stats */}
          <div className="mb-5 grid grid-cols-2 gap-3 sm:grid-cols-3">
            <div className="rounded-lg border border-slate-200 bg-slate-50 px-4 py-3">
              <p className="text-xs font-medium uppercase tracking-wider text-slate-400">Total Utilizadores</p>
              <p className="mt-1 text-2xl font-bold text-slate-800">{users.length}</p>
            </div>
            <div className="rounded-lg border border-slate-200 bg-slate-50 px-4 py-3">
              <p className="text-xs font-medium uppercase tracking-wider text-slate-400">Com Projeto Ativo</p>
              <p className="mt-1 text-2xl font-bold text-emerald-600">{usersWithProject.length}</p>
            </div>
            <div className="rounded-lg border border-slate-200 bg-slate-50 px-4 py-3">
              <p className="text-xs font-medium uppercase tracking-wider text-slate-400">Sem Projeto</p>
              <p className="mt-1 text-2xl font-bold text-slate-400">{usersWithoutProject.length}</p>
            </div>
          </div>

          {/* Users table */}
          <div className="overflow-x-auto rounded-xl border border-slate-200">
            <table className="w-full">
              <thead>
                <tr className="border-b border-slate-200 bg-slate-50/50">
                  <th className="px-4 py-2.5 text-left text-xs font-semibold uppercase tracking-wider text-slate-500">ID</th>
                  <th className="px-4 py-2.5 text-left text-xs font-semibold uppercase tracking-wider text-slate-500">Utilizador</th>
                  <th className="px-4 py-2.5 text-left text-xs font-semibold uppercase tracking-wider text-slate-500">Papel (Roles)</th>
                  <th className="px-4 py-2.5 text-left text-xs font-semibold uppercase tracking-wider text-slate-500">Projeto Ativo</th>
                </tr>
              </thead>
              <tbody className="divide-y divide-slate-100">
                {users.map((u) => (
                  <tr key={u.id} className="transition hover:bg-slate-50/60">
                    <td className="px-4 py-3">
                      <code className="rounded bg-slate-100 px-1.5 py-0.5 text-xs text-slate-500">{String(u.id)}</code>
                    </td>
                    <td className="px-4 py-3">
                      <div className="flex items-center gap-2.5">
                        <div className="flex h-8 w-8 shrink-0 items-center justify-center rounded-full bg-slate-100 text-xs font-bold text-slate-500">
                          {(u.nickname || u.email).charAt(0).toUpperCase() || '?'}
                        </div>
                        <div className="min-w-0">
                          <p className="truncate text-sm font-medium text-slate-700">{u.nickname || 'Sem nome'}</p>
                          <p className="truncate text-xs text-slate-400">{u.email || 'Sem email'}</p>
                        </div>
                      </div>
                    </td>
                    <td className="px-4 py-3">
                      <span className={`inline-flex items-center gap-1.5 rounded-full px-2.5 py-1 text-xs font-medium ${roleBadgeClass(u.roles)}`}>
                        {roleIcon(u.roles)}
                        {roleLabel(u.roles)}
                      </span>
                    </td>
                    <td className="px-4 py-3">
                      {u.active_project ? (
                        <span className="inline-flex items-center gap-1.5 rounded-full bg-emerald-50 px-2.5 py-1 text-xs font-medium text-emerald-700 ring-1 ring-emerald-200">
                          <span className="h-2 w-2 rounded-full bg-emerald-500" />
                          {u.active_project.nome}
                        </span>
                      ) : (
                        <span className="text-xs text-slate-400">Nenhum projeto ativo</span>
                      )}
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>

          {/* Grouped by project */}
          {usersWithProject.length > 0 && (
            <div className="mt-6">
              <h4 className="mb-3 text-sm font-bold text-slate-600">Utilizadores Agrupados por Projeto</h4>
              <div className="space-y-3">
                {Object.entries(
                  usersWithProject.reduce<Record<string, { projectName: string; users: UserWithProject[] }>>((acc, u) => {
                    const key = String(u.active_project!.id);
                    if (!acc[key]) acc[key] = { projectName: u.active_project!.nome, users: [] };
                    acc[key].users.push(u);
                    return acc;
                  }, {}),
                ).map(([projId, group]) => (
                  <div key={projId} className="rounded-xl border border-slate-200 overflow-hidden">
                    <div className="flex items-center justify-between bg-slate-50 px-4 py-3 border-b border-slate-200">
                      <div className="flex items-center gap-2">
                        <div className="flex h-7 w-7 items-center justify-center rounded-lg text-white text-xs font-bold" style={{ background: TLM_PRIMARY }}>
                          {group.projectName.charAt(0).toUpperCase()}
                        </div>
                        <span className="text-sm font-bold text-slate-700">{group.projectName}</span>
                      </div>
                      <span className="rounded-full bg-slate-200 px-2 py-0.5 text-xs font-medium text-slate-600">
                        {group.users.length} {group.users.length === 1 ? 'utilizador' : 'utilizadores'}
                      </span>
                    </div>
                    <div className="divide-y divide-slate-100">
                      {group.users.map((u) => (
                        <div key={u.id} className="flex items-center gap-3 px-4 py-3 transition hover:bg-slate-50/60">
                          <div className="flex h-8 w-8 shrink-0 items-center justify-center rounded-full bg-slate-100 text-xs font-bold text-slate-500">
                            {(u.nickname || u.email).charAt(0).toUpperCase() || '?'}
                          </div>
                          <div className="min-w-0 flex-1">
                            <p className="truncate text-sm font-medium text-slate-700">{u.nickname || 'Sem nome'}</p>
                            <p className="truncate text-xs text-slate-400">{u.email}</p>
                          </div>
                          <span className={`inline-flex items-center gap-1.5 rounded-full px-2.5 py-1 text-xs font-medium ${roleBadgeClass(u.roles)}`}>
                            {roleIcon(u.roles)}
                            {roleLabel(u.roles)}
                          </span>
                        </div>
                      ))}
                    </div>
                  </div>
                ))}
              </div>
            </div>
          )}
        </div>
      )}
    </div>
  );
}

import { useEffect, useState, useCallback, useMemo, type ReactNode } from 'react';
import * as echarts from 'echarts/core';
import { TreemapChart, BarChart } from 'echarts/charts';
import { TooltipComponent, VisualMapComponent, GridComponent } from 'echarts/components';
import { CanvasRenderer } from 'echarts/renderers';
import ReactECharts from 'echarts-for-react/lib/core';
import type { EChartsOption } from 'echarts';
import {
  Stethoscope, Users, UserCheck, ClipboardList, Target, TrendingUp,
  Calendar, Loader2, AlertTriangle, RefreshCw, MapPin, HeartHandshake,
  Award, BarChart3,
} from 'lucide-react';

echarts.use([TreemapChart, BarChart, TooltipComponent, VisualMapComponent, GridComponent, CanvasRenderer]);
import { fetchRecords, DatabaseError } from '@/services/database';
import { useToast } from '@/components/Toast';
import { useProject } from '@/hooks/useProject';
import DynamicDashboard from '@/components/DynamicDashboard';
import { TLM_PRIMARY, TLM_SECONDARY } from '@/config/theme';
import type { TableCollection } from '@/types/database';

interface ScreeningRecord {
  id: string | number;
  diagnosis: string | null;
  suspected_leprosy: string | null;
  screening_date: string | null;
  createdAt: string;
  districtId: string | number | null;
  villageId: string | number | null;
  village?: { name: string; geoDistrictId: string | number } | null;
  district?: { DistrictName: string; id: string | number } | null;
  beneficiary?: { gender: string | null; age: number | null } | null;
  beneficiaryId: string | number | null;
  [key: string]: unknown;
}

interface DistrictData {
  name: string;
  total: number;
  confirmed: number;
  male: number;
  female: number;
  mb: number;
  pb: number;
}

interface LiderancaRecord {
  id: string | number;
  tipo_de_lideranca: string | null;
  districtId?: string | number | null;
  district?: { DistrictName: string; id: string | number } | null;
  [key: string]: unknown;
}

export default function AnalyticsDashboard({ collections }: { collections?: TableCollection[] }) {
  const { isOlikanassa } = useProject();

  if (!isOlikanassa && collections) {
    return <DynamicDashboard collections={collections} />;
  }

  return <OlikanassaDashboard />;
}

function OlikanassaDashboard() {
  const { notify } = useToast();
  const [screenings, setScreenings] = useState<ScreeningRecord[]>([]);
  const [liderancas, setLiderancas] = useState<LiderancaRecord[]>([]);
  const [districts, setDistricts] = useState<Map<string, string>>(new Map());
  const [membersCount, setMembersCount] = useState(0);
  const [goalsCount, setGoalsCount] = useState(0);
  const [outcomesCount, setOutcomesCount] = useState(0);
  const [indicatorMeasurements, setIndicatorMeasurements] = useState<number>(0);
  const [indicatorPlanned, setIndicatorPlanned] = useState<number>(0);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  const [dateFrom, setDateFrom] = useState('');
  const [dateTo, setDateTo] = useState('');
  const [districtFilter, setDistrictFilter] = useState('all');

  const loadDistricts = useCallback(async () => {
    try {
      const data = await fetchRecords('districts', { page: 1, pageSize: 100 });
      const map = new Map<string, string>();
      for (const d of data.data) {
        map.set(String(d.id), (d.DistrictName as string) || `Distrito ${d.id}`);
      }
      setDistricts(map);
    } catch {
      // non-critical
    }
  }, []);

  const loadCounts = useCallback(async () => {
    const safeCount = async (table: string): Promise<number> => {
      try {
        const data = await fetchRecords(table, { page: 1, pageSize: 1 });
        return data.meta?.count ?? 0;
      } catch {
        return 0;
      }
    };
    setMembersCount(await safeCount('members'));
    setGoalsCount(await safeCount('goals'));
    setOutcomesCount(await safeCount('Outcomes1'));

    try {
      const data = await fetchRecords('indicator_measurements', { page: 1, pageSize: 1 });
      setIndicatorMeasurements(data.meta?.count ?? 0);
    } catch {
      setIndicatorMeasurements(0);
    }

    try {
      const data = await fetchRecords('Indicator_Catalog', { page: 1, pageSize: 100 });
      let planned = 0;
      for (const rec of data.data) {
        const val = rec.valor_planeado ?? rec.planned_value ?? rec.meta ?? rec.target;
        if (val != null) planned += Number(val) || 0;
      }
      setIndicatorPlanned(planned);
    } catch {
      setIndicatorPlanned(0);
    }
  }, []);

  const loadScreenings = useCallback(async () => {
    setLoading(true);
    setError(null);
    try {
      const allScreenings: ScreeningRecord[] = [];
      let page = 1;
      const pageSize = 100;
      while (true) {
        const data = await fetchRecords('screenings', {
          page, pageSize,
          appends: ['district', 'village', 'beneficiary'],
        });
        allScreenings.push(...(data.data as ScreeningRecord[]));
        if (page >= data.meta.totalPage) break;
        page++;
      }
      setScreenings(allScreenings);
    } catch (err) {
      if (err instanceof DOMException && err.name === 'AbortError') return;
      const msg = err instanceof DatabaseError ? err.message : 'Falha ao carregar os dados de rastreio.';
      setError(msg);
      notify('error', msg);
    } finally {
      setLoading(false);
    }
  }, [notify]);

  const loadLiderancas = useCallback(async () => {
    try {
      const all: LiderancaRecord[] = [];
      let page = 1;
      const pageSize = 100;
      while (true) {
        const data = await fetchRecords('liderancas', {
          page, pageSize,
          appends: ['district'],
        });
        all.push(...(data.data as LiderancaRecord[]));
        if (page >= data.meta.totalPage) break;
        page++;
        if (page > 20) break;
      }
      setLiderancas(all);
    } catch {
      setLiderancas([]);
    }
  }, []);

  useEffect(() => {
    loadDistricts();
    loadCounts();
    loadScreenings();
    loadLiderancas();
  }, [loadDistricts, loadCounts, loadScreenings, loadLiderancas]);

  const filteredScreenings = useMemo(() => {
    return screenings.filter((s) => {
      if (dateFrom) {
        const d = s.screening_date || s.createdAt;
        if (d && new Date(d) < new Date(dateFrom)) return false;
      }
      if (dateTo) {
        const d = s.screening_date || s.createdAt;
        if (d && new Date(d) > new Date(dateTo)) return false;
      }
      if (districtFilter !== 'all') {
        const dName = getDistrictName(s, districts);
        if (dName !== districtFilter) return false;
      }
      return true;
    });
  }, [screenings, dateFrom, dateTo, districtFilter, districts]);

  const filteredLiderancas = useMemo(() => {
    if (districtFilter === 'all') return liderancas;
    return liderancas.filter((l) => {
      const dName = l.district?.DistrictName ?? '';
      return dName === districtFilter;
    });
  }, [liderancas, districtFilter]);

  const confirmedCases = useMemo(
    () => filteredScreenings.filter((s) => s.diagnosis === 'Lepra' || s.diagnosis === 'MB' || s.diagnosis === 'PB').length,
    [filteredScreenings],
  );

  // CATEGORY 1: M&A data
  const goalsProgress = useMemo(() => {
    if (goalsCount === 0) return 0;
    return Math.min(100, Math.round((outcomesCount / goalsCount) * 100));
  }, [goalsCount, outcomesCount]);

  const indicatorProgress = useMemo(() => {
    if (indicatorPlanned === 0) return 0;
    return Math.min(100, Math.round((indicatorMeasurements / indicatorPlanned) * 100));
  }, [indicatorMeasurements, indicatorPlanned]);

  // CATEGORY 2: Lepra treemap
  const districtDataMap = useMemo(() => {
    const map = new Map<string, DistrictData>();
    for (const s of filteredScreenings) {
      const dName = getDistrictName(s, districts) || 'Sem Distrito';
      if (!map.has(dName)) {
        map.set(dName, { name: dName, total: 0, confirmed: 0, male: 0, female: 0, mb: 0, pb: 0 });
      }
      const d = map.get(dName)!;
      d.total++;
      if (s.diagnosis === 'Lepra' || s.diagnosis === 'MB' || s.diagnosis === 'PB') d.confirmed++;
      if (s.diagnosis === 'MB') d.mb++;
      if (s.diagnosis === 'PB') d.pb++;
      if (s.beneficiary?.gender === 'male') d.male++;
      if (s.beneficiary?.gender === 'female') d.female++;
    }
    return Array.from(map.values()).sort((a, b) => b.total - a.total);
  }, [filteredScreenings, districts]);

  const treemapOption = useMemo<EChartsOption>(() => {
    const treemapData = districtDataMap.map((d) => ({
      name: d.name,
      value: d.total,
      confirmed: d.confirmed,
      male: d.male,
      female: d.female,
      mb: d.mb,
      pb: d.pb,
    }));

    return {
      tooltip: {
        // eslint-disable-next-line @typescript-eslint/no-explicit-any
        formatter: (info: any) => {
          const d = info.data;
          return `<b>${d.name}</b><br/>Total: ${d.value}<br/>Confirmados: ${d.confirmed}<br/>Homens: ${d.male} | Mulheres: ${d.female}<br/>MB: ${d.mb} | PB: ${d.pb}`;
        },
      },
      series: [
        {
          type: 'treemap',
          roam: true,
          nodeClick: 'zoomToNode',
          data: treemapData,
          breadcrumb: { show: true, bottom: 5 },
          label: {
            show: true,
            // eslint-disable-next-line @typescript-eslint/no-explicit-any
            formatter: (info: any) => {
              const d = info.data;
              const name = d.name ?? '';
              const value = d.value ?? 0;
              const confirmed = d.confirmed ?? 0;
              const male = d.male ?? 0;
              const female = d.female ?? 0;
              return `{name|${name}}{count|${value}}\n{sub|Confirmados: ${confirmed} | H: ${male} | M: ${female}}`;
            },
            rich: {
              name: {
                fontSize: 14,
                fontWeight: 'bold',
                color: '#fff',
                align: 'left',
                padding: [0, 0, 0, 4],
              },
              count: {
                fontSize: 24,
                fontWeight: 'bold',
                color: '#fff',
                align: 'right',
                padding: [0, 4, 0, 0],
              },
              sub: {
                fontSize: 11,
                color: 'rgba(255,255,255,0.85)',
                align: 'left',
                padding: [4, 0, 0, 4],
              },
            },
          },
          upperLabel: { show: true, height: 30 },
          itemStyle: { borderColor: '#fff', borderWidth: 2, gapWidth: 2 },
          levels: [
            {
              itemStyle: { borderColor: '#fff', borderWidth: 0, gapWidth: 0 },
            },
            {
              colorSaturation: [0.35, 0.5],
              itemStyle: { borderColor: '#fff', borderWidth: 2, gapWidth: 2 },
            },
          ],
        },
      ],
    };
  }, [districtDataMap]);

  // CATEGORY 3: Lideranças bar chart
  const liderancaTypeData = useMemo(() => {
    const map = new Map<string, number>();
    for (const l of filteredLiderancas) {
      const tipo = l.tipo_de_lideranca || 'Não especificado';
      map.set(tipo, (map.get(tipo) ?? 0) + 1);
    }
    return Array.from(map.entries())
      .map(([label, value]) => ({ label, value }))
      .sort((a, b) => b.value - a.value);
  }, [filteredLiderancas]);

  const liderancasChartOption = useMemo<EChartsOption>(() => {
    if (liderancaTypeData.length === 0) return {} as EChartsOption;

    return {
      tooltip: {
        trigger: 'axis',
        axisPointer: { type: 'shadow' },
      },
      grid: { left: '3%', right: '8%', bottom: '3%', top: '3%', containLabel: true },
      xAxis: { type: 'value' },
      yAxis: {
        type: 'category',
        data: liderancaTypeData.map((g) => g.label),
        axisLabel: { fontSize: 12 },
      },
      series: [{
        type: 'bar',
        data: liderancaTypeData.map((g) => g.value),
        itemStyle: {
          color: new echarts.graphic.LinearGradient(0, 0, 1, 0, [
            { offset: 0, color: '#10b981' },
            { offset: 1, color: '#059669' },
          ]),
          borderRadius: [0, 6, 6, 0],
        },
        label: {
          show: true,
          position: 'right',
          fontSize: 13,
          fontWeight: 'bold',
          color: '#334155',
        },
        barMaxWidth: 40,
      }],
    };
  }, [liderancaTypeData]);

  const handleRefresh = () => {
    loadScreenings();
    loadCounts();
    loadLiderancas();
  };

  const availableDistricts = useMemo(() => {
    const set = new Set<string>();
    for (const s of screenings) {
      const name = getDistrictName(s, districts);
      if (name) set.add(name);
    }
    for (const l of liderancas) {
      if (l.district?.DistrictName) set.add(l.district.DistrictName);
    }
    return Array.from(set).sort();
  }, [screenings, districts, liderancas]);

  if (loading && screenings.length === 0) {
    return (
      <div className="flex h-full items-center justify-center p-8">
        <div className="flex flex-col items-center gap-4">
          <Loader2 className="h-8 w-8 animate-spin text-slate-400" />
          <p className="text-sm text-slate-500">A carregar dados analíticos...</p>
        </div>
      </div>
    );
  }

  return (
    <div className="flex h-full flex-col overflow-hidden">
      {/* Header */}
      <div className="flex flex-col gap-3 border-b border-slate-200 bg-white px-4 py-3 md:flex-row md:items-center md:justify-between md:px-6 md:py-4">
        <div className="flex items-center gap-3">
          <div className="flex h-9 w-9 shrink-0 items-center justify-center rounded-xl text-white md:h-10 md:w-10" style={{ background: `linear-gradient(135deg, ${TLM_PRIMARY}, ${TLM_SECONDARY})` }}>
            <BarChart3 className="h-4 w-4 md:h-5 md:w-5" />
          </div>
          <div>
            <h2 className="text-base font-bold text-slate-900 md:text-lg">Dashboard Analítico · Olikanassa</h2>
            <p className="text-xs text-slate-400">Monitorização, Avaliação & Controlo de Lepra</p>
          </div>
